Lemma le4_two_bytes : forall b0 b1 : Z, 0 <= b0 < 256 -> 0 <= b1 < 256 ->
  le4 (Z_to_bv 64 (b0 + 256 * b1)) = [Z_to_bv 8 b0; Z_to_bv 8 b1; Z_to_bv 8 0; Z_to_bv 8 0].
